	Ref<AudioSample> sample;
	sample.instantiate();
	sample->loop_mode =
		loop ? AudioSample::LoopMode::LOOP_FORWARD : AudioSample::LoopMode::LOOP_DISABLED;
	sample->loop_begin = loop_offset;
	sample->loop_end = 0;
	return sample
;
