RID GodotPhysicsServer2D::_shape_create(PS2DE::ShapeType p_shape)
{
	ERR_FAIL_COND_V(p_shape == PS2DE::SHAPE_CUSTOM, RID());

	GodotShape2D* shape = memnew(GodotShape2D(p_shape));

	RID id = shape_owner.make_rid(shape);
	shape->set_self(id);

	return id;
}

